static const double MAHA_MEAN[6] = {
    0.074193790555000305,
    16.711566925048828,
    1.8825006484985352,
    48.596138000488281,
    0.07298675924539566,
    1.8394724130630493
};

static const double MAHA_INV_COV[36] = {
    586.38636789196801,
    0.86008771921979355,
    -2.6631220636367314,
    -0.061985337167192865,
    -6.5694616180181749,
    3.8369072800668182,
    0.86008771921979366,
    0.10778953332912944,
    -0.01430849687946908,
    8.9573875678843894e-05,
    0.01428705046083254,
    0.0091118455170698023,
    -2.6631220636368131,
    -0.014308496879469154,
    3.2981151471179535,
    -0.078249691420132855,
    -0.35052432143643847,
    0.37865881434975296,
    -0.061985337167187786,
    8.9573875678847811e-05,
    -0.078249691420132883,
    0.0049452997104181351,
    -0.0019620364796754616,
    -0.10522497563683764,
    -6.5694616180181633,
    0.014287050460832557,
    -0.3505243214364398,
    -0.0019620364796754269,
    0.8646157806335506,
    0.24064663662102292,
    3.836907280066761,
    0.0091118455170698665,
    0.3786588143497524,
    -0.10522497563683762,
    0.24064663662102381,
    4.6826540993111223
};

static const double MAHA_THRESHOLD = 10.104021265036314;

double maha_distance(const double *x)
{
    double diff[CAN_IDS_NUM_FEATURES];
    double dist2 = 0.0;

    for (int i = 0; i < CAN_IDS_NUM_FEATURES; ++i) {
        diff[i] = x[i] - MAHA_MEAN[i];
    }

    for (int i = 0; i < CAN_IDS_NUM_FEATURES; ++i) {
        double s = 0.0;

        for (int j = 0; j < CAN_IDS_NUM_FEATURES; ++j) {
            s += MAHA_INV_COV[i * CAN_IDS_NUM_FEATURES + j] * diff[j];
        }

        dist2 += diff[i] * s;
    }

    /*
     * Numerical round-off can theoretically produce a tiny negative
     * quadratic form near zero. Clamp before sqrt.
     */
    if (dist2 < 0.0 && dist2 > -1e-12) {
        dist2 = 0.0;
    }

    return sqrt(dist2);
}

int maha_predict(const double *x)
{
    return maha_distance(x) > MAHA_THRESHOLD ? 1 : 0;
}

int can_ids_predict(const double *x)
{
    double scores[CAN_IDS_NUM_CLASSES];

    score(x, scores);

    int best = 0;

    for (int i = 1; i < CAN_IDS_NUM_CLASSES; ++i) {
        if (scores[i] > scores[best]) {
            best = i;
        }
    }

    /*
     * Known attack predicted by LightGBM:
     * return immediately.
     */
    if (best != NORMAL_IDX) {
        return CODE_MAP[best];
    }

    /*
     * LightGBM predicted normal:
     * use frozen V2 Mahalanobis detector for unknown anomaly.
     */
    if (maha_predict(x)) {
        return 5;
    }

    return 0;
}
